var closedRaw = $context.$nodes.GET_SUPPLIER_NEGOTIATIONS_DATA.$output.items || [];
var awardByDateRaw = $context.$nodes.GET_AWARD_BY_DATE_NEGOTIATIONS.$output.items || [];

var seenKeys = "";
var mergedList = [];

for (var i = 0; i < closedRaw.length; i++) {
  var item = closedRaw[i];
  var id = item.AuctionHeaderId;
  var marker = '|' + id + '|';
  var alreadySeen = seenKeys.indexOf(marker) >= 0;

  if (alreadySeen) continue;

  var closeMs = Date.parse(item.CloseDate);
  var nowMs = Date.parse(item.CurrentDateTime);
  var diffInDays = (nowMs - closeMs) / 86400000;
  seenKeys = seenKeys + marker;
  mergedList[mergedList.length] = {
    AuctionHeaderId: id,
    NegotiationStatus: item.NegotiationStatusCode,
    DifferenceInDays: diffInDays,
    ProcurementBU: item.ProcurementBU,
    SupplierResponses: item.SupplierResponses,
    CloseDate: item.CloseDate,
    AwardByDate: item.AwardByDate,
    SuppliersCount: item.SuppliersCount,
    RestrictToInvitedSuppliersFlag: item.RestrictToInvitedSuppliersFlag,
    NegotiationTitle: item.NegotiationType + ' ' + item.Negotiation + ' - ' + (item.NegotiationTitle || ' '),
    BuyerName: item.Buyer || ' '
  };
}

for (var j = 0; j < awardByDateRaw.length; j++) {
  var item2 = awardByDateRaw[j];
  var id2 = item2.AuctionHeaderId;
  var marker2 = '|' + id2 + '|';
  var alreadySeen2 = seenKeys.indexOf(marker2) >= 0;

  if (alreadySeen2) continue;
  if (item2.AwardByDate == null) continue;

  var awardMs = Date.parse(item2.AwardByDate);
  var nowMs2 = Date.parse(item2.CurrentDateTime);
  var diffInDays2 = (awardMs - nowMs2) / 86400000;

  if (diffInDays2 >= 0) continue;

  seenKeys = seenKeys + marker2;
  mergedList[mergedList.length] = {
    AuctionHeaderId: id2,
    NegotiationStatus: item2.NegotiationStatusCode + '_AWARD_BY_DATE',
    DifferenceInDays: diffInDays2,
    ProcurementBU: item2.ProcurementBU,
    SupplierResponses: item2.SupplierResponses,
    CloseDate: item2.CloseDate,
    AwardByDate: item2.AwardByDate,
    SuppliersCount: item2.SuppliersCount,
    RestrictToInvitedSuppliersFlag: item2.RestrictToInvitedSuppliersFlag,
    NegotiationTitle: item2.NegotiationType + ' ' + item2.Negotiation + ' - ' + (item2.NegotiationTitle || ' '),
    BuyerName: item2.Buyer || ' '
  };
}

return { NegotiationsList: mergedList, NegotiationsCount: mergedList.length };

//const suggestedAction = $context.$app.$OraAction;

const suggestedAction = $context.$system.$inputMessage;
const [action, auctionHeaderId] = suggestedAction .split("-", 2);

return {Action: action, AuctionHeaderId: auctionHeaderId};
